[HttpPost("clientes")]
public IActionResult Criar(ClienteDto dto) {
  try {
    if (string.IsNullOrEmpty(dto.Email)) return BadRequest();
    var cliente = new Cliente { Nome = dto.Nome, Email = dto.Email, CriadoEm = DateTime.Now };
    _ctx.Clientes.Add(cliente);
    _ctx.SaveChanges();
